bin.bootstrap:
runHfLint({ argv: process.argv.slice(2), cwd: process.cwd(), stdin: 0, stdout: process.stdout, stderr: process.stderr }).then(
  (code) => { process.exitCode = code },
  (error) => {
    process.stderr.write((error instanceof Error ? error.message : String(error)) + '\n')
    process.exitCode = 2
  }
)
